------------ import ------------

------------ define ------------
local ParamIds = {
    BasicConvert = 17,
    GrowingConvert = 18,
    Adult = 19, ---成熟型
}
------------ define ------------

--- from: Assets/BundleResources/Prefabs/OverseaManage/OverseaManageCatballSettingPopup.prefab
---@class MaidCoffeeCatSettingDialog
---@field Env                            MaidCoffeeCatSettingDialog
---@field controller                        Engine.UI.UILuaDialog
---@field CatballType3                    UnityEngine.RectTransform
---@field CatballType2                    UnityEngine.RectTransform
---@field CatballType1                    UnityEngine.RectTransform
---@field FontStyleWithIconButton        UnityEngine.RectTransform
---@field BtnClose                        UnityEngine.RectTransform
local MaidCoffeeCatSettingDialog = Class("MaidCoffeeCatSettingDialog")

function MaidCoffeeCatSettingDialog:__init()
    self.pool = nil
    self.toggles = {}
end

function MaidCoffeeCatSettingDialog:__delete()
    self.pool = nil
    self.controller = nil
    self.toggles = nil
end

function MaidCoffeeCatSettingDialog:Awake()
    SetButtonAction(self.BtnClose.gameObject, function()
        UIModule.BackDialog()
    end)
    SetButtonAction(self.FontStyleWithIconButton.gameObject, function()
        ---设置按钮的逻辑
        local t = {}
        for i, v in pairs(self.toggles) do
            if v then
                table.insert(t, checkNumber(v))
            end
        end
        local data = ''
        if #t > 0 then
            data = table.concat(t, ',')
        end
        GameUtils.Request(Interfaces.MaidCoffeeCatCallSetting, { qualities = data }, function(request, response)
            if checkNumber(response.errCode) == 0 then
                ---@type CatEggComponent
                local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
                eggComponent:SetAutoConvertStetting(t)
                GameUtils.Toast(localize('设置成功'))
            end
        end)
    end)
end

---SetConvertType
---@param trans UnityEngine.Transform
---@param position number
---@param id number
function MaidCoffeeCatSettingDialog:SetConvertType(trans, position, id)
    local bgTrans = trans:Find("ImgBg")
    local textTrans = trans:Find("Desc/TextNumber")
    local toggleTrans = trans:Find("ToggleSelect")
    ---@type MaidCoffeeManagerSettingVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", position)
    CfUtils.FillText(textTrans.gameObject, string.format("1:%d", vo.num))
    ---@type UnityEngine.UI.Toggle
    local toggle = KTool.GetComponent(toggleTrans.gameObject, typeof(Toggle))
    if self.toggles[tostring(id)] then
        toggle:SetIsOnWithoutNotify(true)
        CfUtils.SetUISwitchImage(bgTrans, 2)
    else
        CfUtils.SetUISwitchImage(bgTrans, 1)
    end
    toggle.onValueChanged:RemoveAllListeners()
    toggle.onValueChanged:AddListener(function(isOn)
        if isOn then
            self.toggles[tostring(id)] = id
        else
            self.toggles[tostring(id)] = nil
        end
        toggle.isOn = isOn
    end)
end

function MaidCoffeeCatSettingDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local initParams = self.controller.Argument.parameters
        local pools = initParams.data
        self.pool = table.takeFirst(pools)
        ---@type CatEggComponent
        local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        local t = eggComponent:GetAutoConvertStetting()
        if t and #t > 0 then
            for i, v in pairs(t) do
                self.toggles[tostring(v)] = checkNumber(v)
            end
        end

        self:SetConvertType(self.CatballType1.transform, ParamIds.BasicConvert, 1)
        self:SetConvertType(self.CatballType2.transform, ParamIds.GrowingConvert, 2)
        self:SetConvertType(self.CatballType3.transform, ParamIds.Adult, 3)
    end))
    return coWait
end

function MaidCoffeeCatSettingDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return MaidCoffeeCatSettingDialog